// Oct 14 (arenas-import, Evan approved): places the reskin-incoming obstacle sets (ZoogiObstacles.inl, generated by
// Scripts/arenas/gen_obstacles.py) on their arena at build time, after the pack dressing. Meadow = batch 6, Night Circuit = rev 18.1.
// The other packs (Volcanic 12.1, Cosmic r2015, Arabian 3.1, Tomb 26.1) are authored for the A 1.3 court (ring-out r2015);
// those arenas still play on r1550 on main, so they are not placed until the court scale is ruled on (see PROGRESS.md).
// Built with the arena, so the main-menu map preview (which shows the live arena, forming snapped) shows them as well.
#include "ZoogiArena.h"
#include "ZoogiObstacle.h"
#include "ZoogiStageForming.h"
#include "ZoogiPhysics.h"
#include "ZoogiRoll.h"
#include "Engine/StaticMesh.h"
#include "Engine/World.h"
#include "Misc/CommandLine.h"
#include "ZoogiObstacles.inl"

void AZoogiArena::PlaceObstacles()
{
	if (FParse::Param(FCommandLine::Get(), TEXT("ZoogiNoObstacles"))) return;
	const int32 Th = (int32)Theme;
	int32 N = 0, NMiss = 0, NTrig = 0, NHull = 0, NSolid = 0;
	const float KR = GetKnockoffRadius();
	for (int32 i = 0; i < UE_ARRAY_COUNT(ZoogiObs::Insts); ++i)
	{
		const ZoogiObs::FInst& In = ZoogiObs::Insts[i];
		if (In.Theme != Th) continue;
		const ZoogiObs::FMeshDef& M = ZoogiObs::Meshes[In.Mesh];
		FActorSpawnParameters SP;
		SP.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
		const FVector Loc = GetActorLocation() + FVector(In.X, In.Y, In.Z);
		AZoogiObstacle* O = GetWorld()->SpawnActor<AZoogiObstacle>(AZoogiObstacle::StaticClass(), FTransform(FRotator(0.f, In.Yaw, 0.f), Loc), SP);
		if (!O) continue;
		O->ObsName = FName(In.Name);
		float Top = 0.f;
		for (int32 k = 0; k < M.VisNum + M.SpentNum; ++k)
		{
			const bool bSpent = k >= M.VisNum;
			UStaticMesh* SM = LoadObject<UStaticMesh>(nullptr, ZoogiObs::Paths[(bSpent ? M.SpentFirst - M.VisNum : M.VisFirst) + k]);
			if (!SM) { ++NMiss; continue; }
			O->AddVisual(SM, In.Scale, bSpent);
			Top = FMath::Max(Top, SM->GetBoundingBox().Max.Z * In.Scale);
		}
		if (In.bCollide && M.HullNum > 0)
		{
			TArray<TArray<FVector>> Hulls;
			for (int32 h = 0; h < M.HullNum; ++h)
			{
				const ZoogiObs::FHull& H = ZoogiObs::Hulls[M.HullFirst + h];
				TArray<FVector>& Pts = Hulls.AddDefaulted_GetRef();
				for (int32 p = 0; p < H.PtNum; ++p) { const float* F = &ZoogiObs::Pts[(H.PtFirst + p) * 3]; Pts.Add(FVector(F[0], F[1], F[2])); }
			}
			O->BuildCollider(Hulls, In.Scale, ZoogiPhysics::MakeMaterial(O, In.Friction, In.Restitution, false));
			NHull += O->NumHulls; ++NSolid;
		}
		O->BounceGain = In.BounceGain; O->MaxOut = In.MaxOut;
		for (const ZoogiObs::FTrig& T : ZoogiObs::Trigs)
		{
			if (T.Inst != i) continue;
			FZoogiObsTrigger& Z = O->Triggers.AddDefaulted_GetRef();
			Z.Kind = T.Kind; Z.Shape = T.Shape;
			Z.C = FVector(T.C[0], T.C[1], T.C[2]); Z.E = FVector(T.E[0], T.E[1], T.E[2]); Z.D = FVector2D(T.D[0], T.D[1]);
			for (int32 q = 0; q < 4; ++q) Z.P[q] = T.P[q];
			++NTrig;
		}
		Obstacles.Add(O);
		++N;
		if (Forming)
		{
			const float Rd = FVector2D(In.X, In.Y).Size();
			Forming->AddActor(O, EZoogiFormStyle::Rise, FVector(0.f, 0.f, -(FMath::Max(Top, 20.f) + 120.f)), 0.35f + 0.9f * FMath::Clamp(Rd / FMath::Max(KR, 1.f), 0.f, 1.f), 0.7f, 6.f);
		}
	}
	if (N) UE_LOG(LogZoogi, Log, TEXT("Obstacles (theme %d): %d placed, %d solid (%d convex hulls, BlockAll), %d triggers, %d missing meshes; unbreakable, not in Crystal Collapse"), Th, N, NSolid, NHull, NTrig, NMiss);
}
